// WMO weather code -> icon id, or null when there is no icon for it (the codes are
// the ones WeatherView.condition() names).
function forCode(wmo) {
    // Number(null) is 0 — and a source that gave no code did not say "clear".
    if (wmo === null || wmo === undefined || wmo === "")
        return null
    switch (Number(wmo)) {
    case 0: return "clear"
    case 1: return "mostly-clear"
    case 2: return "partly"
    case 3: return "overcast"
    case 45: case 48: return "fog"
    case 51: case 53: case 55: case 56: case 57: return "drizzle"
    case 61: case 63: case 65: case 66: case 67: return "rain"
    case 80: case 81: case 82: return "showers"
    case 71: case 73: case 77: return "snow"
    case 75: case 85: case 86: return "snow-heavy"
    case 95: return "thunder"
    case 96: case 99: return "thunder-hail"
    default: return null
    }
}
